{
  "name": "opencode-optmem",
  "version": "0.1.1",
  "description": "Native OptMem integration for OpenCode",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/gustavo-ferreira03/opencode-optmem.git"
  },
  "homepage": "https://github.com/gustavo-ferreira03/opencode-optmem#readme",
  "bugs": {
    "url": "https://github.com/gustavo-ferreira03/opencode-optmem/issues"
  },
  "main": "./dist/server.js",
  "exports": {
    ".": "./dist/server.js",
    "./server": "./dist/server.js",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "INSTALL.txt"
  ],
  "engines": {
    "bun": ">=1.3.0",
    "opencode": ">=1.18.16 <2"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "optmem",
    "memory"
  ],
  "scripts": {
    "build": "bun scripts/build.ts",
    "check": "bun run checktypes && bun test && bun run build",
    "checktypes": "tsc --noEmit",
    "prepublishOnly": "bun run check",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.18.16",
    "@opentui/core": "0.4.5",
    "@opentui/keymap": "0.4.5",
    "@opentui/solid": "0.4.5",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@types/bun": "^1.3.14",
    "typescript": "^5.9.2"
  }
}
